    # Demo regression patterns (seed locations determine the painted motif).
    patterns={(6,7):[(r,c) for r in range(4,9) for c in range(5,10) if r in (4,8) or c in (5,9)],
      (8,5):[(4,c) for c in range(4,10)]+[(5,9),(6,c) for c in []]}
    # Construct remaining demonstrated motifs explicitly.
    if (mr,mc)==(6,7):
